import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import '@testing-library/jest-dom';
import { LoginForm } from './LoginForm';
import { login } from '../services/authApi';

jest.mock('../services/authApi');
const mockedLogin = jest.mocked(login);

describe('LoginForm', () => {
  beforeEach(() => {
    mockedLogin.mockReset();
  });

  it('renderiza o formulário de login inicialmente', () => {
    render(<LoginForm />);

    expect(screen.getByLabelText('E-mail')).toHaveValue('');
    expect(screen.getByLabelText('Senha')).toHaveValue('');
    expect(screen.getByRole('button', { name: 'Entrar' })).toBeEnabled();
  });

  it('mostra erro ao submeter com campos vazios', async () => {
    const user = userEvent.setup();
    render(<LoginForm />);

    await user.click(screen.getByRole('button', { name: 'Entrar' }));

    expect(screen.getByRole('alert', { name: 'Informe o e-mail.' })).toBeInTheDocument();
    expect(screen.getByRole('alert', { name: 'Informe a senha.' })).toBeInTheDocument();
  });

  it('mostra erro de e-mail inválido', async () => {
    const user = userEvent.setup();
    render(<LoginForm />);

    await user.type(screen.getByLabelText('E-mail'), 'invalid-email');
    await user.click(screen.getByRole('button', { name: 'Entrar' }));

    expect(screen.getByRole('alert', { name: 'E-mail inválido.' })).toBeInTheDocument();
  });

  it('mostra erro de senha curta', async () => {
    const user = userEvent.setup();
    render(<LoginForm />);

    await user.type(screen.getByLabelText('E-mail'), 'test@example.com');
    await user.type(screen.getByLabelText('Senha'), 'short');
    await user.click(screen.getByRole('button', { name: 'Entrar' }));

    expect(screen.getByRole('alert', { name: `A senha deve ter pelo menos 8 caracteres.` })).toBeInTheDocument();
  });

  it('submete com sucesso e chama onSuccess', async () => {
    const user = userEvent.setup();
    const onSuccess = jest.fn();
    mockedLogin.mockResolvedValue({ token: 'token', user: { id: 1, name: 'John Doe' } });
    render(<LoginForm onSuccess={onSuccess} />);

    await user.type(screen.getByLabelText('E-mail'), 'test@example.com');
    await user.type(screen.getByLabelText('Senha'), 'validpassword');
    await user.click(screen.getByRole('button', { name: 'Entrar' }));

    expect(await screen.findByRole('status')).toHaveTextContent('Bem-vindo, John Doe!');
    expect(onSuccess).toHaveBeenCalledWith({ token: 'token', user: { id: 1, name: 'John Doe' } });
  });

  it('mostra mensagem de erro em falha de login', async () => {
    const user = userEvent.setup();
    mockedLogin.mockRejectedValue(new Error('Falha no login'));
    render(<LoginForm />);

    await user.type(screen.getByLabelText('E-mail'), 'test@example.com');
    await user.type(screen.getByLabelText('Senha'), 'validpassword');
    await user.click(screen.getByRole('button', { name: 'Entrar' }));

    expect(await screen.findByRole('alert')).toHaveTextContent('Falha no login');
  });

  it('desabilita botão durante carregamento', async () => {
    const user = userEvent.setup();
    let resolveLogin: () => void;
    mockedLogin.mockImplementation(() => new Promise((resolve) => (resolveLogin = resolve)));
    render(<LoginForm />);

    await user.type(screen.getByLabelText('E-mail'), 'test@example.com');
    await user.type(screen.getByLabelText('Senha'), 'validpassword');
    await user.click(screen.getByRole('button', { name: 'Entrar' }));

    expect(screen.getByRole('button', { name: 'Entrando...' })).toBeDisabled();
    resolveLogin!();
  });

  it('renderiza mensagem de boas-vindas após sucesso', async () => {
    const user = userEvent.setup();
    mockedLogin.mockResolvedValue({ token: 'token', user: { id: 1, name: 'John Doe' } });
    render(<LoginForm />);

    await user.type(screen.getByLabelText('E-mail'), 'test@example.com');
    await user.type(screen.getByLabelText('Senha'), 'validpassword');
    await user.click(screen.getByRole('button', { name: 'Entrar' }));

    expect(await screen.findByRole('status')).toHaveTextContent('Bem-vindo, John Doe!');
  });
});

